"""E-004: .glb в assets/models/ импортируются headless на чистом клоне и не плодят файлов вне CREDITS.md.

Нужно: у каждого .glb в git есть .glb.import с gltf/embedded_image_handling != 1 (иначе импорт выгружает текстуры
PNG рядом с моделью), assets/source/ закрыт .gdignore (иначе Godot видит .blend, ищет Blender и обрывает импорт .glb).
"""
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MODELS = ROOT / "assets" / "models"


def git_tracked(rel):
    return subprocess.run(["git", "ls-files", "--error-unmatch", rel], cwd=ROOT, capture_output=True).returncode == 0


def main():
    bad = []
    if not git_tracked("assets/source/.gdignore"):
        bad.append("assets/source/.gdignore не в git")
    for glb in sorted(MODELS.glob("*.glb")):
        imp = glb.with_name(glb.name + ".import")
        rel = imp.relative_to(ROOT).as_posix()
        if not git_tracked(rel):
            bad.append(f"{rel} не в git")
        elif "gltf/embedded_image_handling=1" in imp.read_text(encoding="utf-8"):
            bad.append(f"{rel}: embedded_image_handling=1 (текстуры выгружаются в assets/models/)")
    subprocess.run(["godot", "--headless", "--path", str(ROOT), "--import"], capture_output=True, cwd=ROOT)
    for glb in sorted(MODELS.glob("*.glb")):
        if not (ROOT / ".godot" / "imported").glob(glb.name + "-*.scn") or \
                not list((ROOT / ".godot" / "imported").glob(glb.name + "-*.scn")):
            bad.append(f"{glb.name}: нет импортированного .scn в .godot/imported")
    extra = [p.name for p in MODELS.iterdir() if p.suffix not in {".glb", ".import"}]
    if extra:
        bad.append("лишние файлы в assets/models/: " + ", ".join(sorted(extra)))
    for b in bad:
        print("FAIL", b)
    print("check_glb_import:", "FAIL" if bad else "ok")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())
